ALTER TABLE place_comment ADD COLUMN root_id BIGINT NULL,ADD COLUMN media LONGBLOB NULL,ADD COLUMN media_type VARCHAR(40) NULL;
UPDATE place_comment SET root_id=parent_id WHERE parent_id IS NOT NULL;
CREATE INDEX idx_comment_root ON place_comment(root_id,id);
UPDATE campus_place SET name=CONCAT('__rename__',name) WHERE name IN ('学生公寓第1组西楼','学生公寓第1组东楼','学生公寓第2组西楼','学生公寓第2组东楼','学生公寓第3组西楼','学生公寓第3组东楼','理科教学科研综合楼北楼','理科教学科研综合楼西楼','理科教学科研综合楼东楼','理科教学科研综合楼南楼','E 教学楼北楼','E 教学楼西楼','E 教学楼东楼','E 教学楼南楼','K2 教学科研综合楼','K3 教学科研综合楼','K5 教学科研综合楼','K6 教学科研综合楼','N1 教学科研综合楼','N2 教学科研综合楼','N3 教学科研综合楼','N4 教学科研综合楼','N5 教学科研综合楼','N6 教学科研综合楼','M1','M2','M3','M4','D1','D2','D3','D4','D5','G1','G2','G3','G4','G5','G6','J1','J2','J3','J4');
UPDATE campus_place SET name=CASE name WHEN '__rename__学生公寓第1组西楼' THEN '凤凰居1号楼（一多书院）' WHEN '__rename__学生公寓第1组东楼' THEN '凤凰居2号楼（从文书院）' WHEN '__rename__学生公寓第2组西楼' THEN '凤凰居5号楼' WHEN '__rename__学生公寓第2组东楼' THEN '凤凰居6号楼' WHEN '__rename__学生公寓第3组西楼' THEN '凤凰居9号楼' WHEN '__rename__学生公寓第3组东楼' THEN '凤凰居10号楼' WHEN '__rename__理科教学科研综合楼北楼' THEN '华岗苑北楼（法学院）' WHEN '__rename__理科教学科研综合楼西楼' THEN '华岗苑西楼（行政办公）' WHEN '__rename__理科教学科研综合楼东楼' THEN '华岗苑东楼' WHEN '__rename__理科教学科研综合楼南楼' THEN '华岗苑南楼（政治学与公共管理学院）' WHEN '__rename__E 教学楼北楼' THEN '振声苑北楼' WHEN '__rename__E 教学楼西楼' THEN '振声苑西楼' WHEN '__rename__E 教学楼东楼' THEN '振声苑东楼' WHEN '__rename__E 教学楼南楼' THEN '振声苑南楼' WHEN '__rename__K2 教学科研综合楼' THEN 'K2 教学科研综合楼（实验中心）' WHEN '__rename__K3 教学科研综合楼' THEN 'K3 教学科研综合楼（海洋研究院）' WHEN '__rename__K5 教学科研综合楼' THEN 'K5 教学科研综合楼（环境科学学院）' WHEN '__rename__K6 教学科研综合楼' THEN 'K6 教学科研综合楼（环境研究院、施工技术研究中心）' WHEN '__rename__N1 教学科研综合楼' THEN 'N1 教学科研综合楼（微生物研究院）' WHEN '__rename__N2 教学科研综合楼' THEN 'N2 教学科研综合楼（生命科学学院北楼）' WHEN '__rename__N3 教学科研综合楼' THEN 'N3 教学科研综合楼（计算机科学与技术学院）' WHEN '__rename__N4 教学科研综合楼' THEN 'N5 教学科研综合楼（信息科学与工程学院）' WHEN '__rename__N5 教学科研综合楼' THEN 'N7 教学科研综合楼' WHEN '__rename__N6 教学科研综合楼' THEN 'N8 教学科研综合楼（生命科学学院南楼）' WHEN '__rename__M1' THEN 'M1 高等研究院' WHEN '__rename__M2' THEN 'M2 高等研究院' WHEN '__rename__M3' THEN 'M3 高等研究院' WHEN '__rename__M4' THEN 'M4 高等研究院' WHEN '__rename__D1' THEN 'D1 工程技术研究院' WHEN '__rename__D2' THEN 'D2 工程技术研究院' WHEN '__rename__D3' THEN 'D3 工程技术研究院' WHEN '__rename__D4' THEN 'D4 工程技术研究院' WHEN '__rename__D5' THEN 'D5 工程技术研究院' WHEN '__rename__G1' THEN 'G1 工程技术研究院' WHEN '__rename__G2' THEN 'G2 工程技术研究院' WHEN '__rename__G3' THEN 'G3 工程技术研究院' WHEN '__rename__G4' THEN 'G4 工程技术研究院' WHEN '__rename__G5' THEN 'G5 工程技术研究院' WHEN '__rename__G6' THEN 'G6 工程技术研究院' WHEN '__rename__J1' THEN 'J1 学院办公' WHEN '__rename__J2' THEN 'J2 学院办公' WHEN '__rename__J3' THEN 'J3 工程技术研究院' WHEN '__rename__J4' THEN 'J4 工程技术研究院' ELSE name END;
